button.danger { color: var(--danger); }
button:disabled { opacity: 0.6; cursor: not-allowed; transform: none; }

#app {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.shell {
  display: grid;
  grid-template-rows: auto auto 1fr;
  height: 100%;
}

.topbar {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.9rem 1rem;
  border-bottom: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.9);
  backdrop-filter: blur(10px);
}

.title-block { display: flex; flex-direction: column; gap: 0.2rem; min-width: 0; }
.app-title { font-size: 1.15rem; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.app-subtitle { font-size: 0.82rem; color: var(--muted); }

.toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(10px);
}

.toolbar .group { display: flex; align-items: center; gap: 0.45rem; }
.toolbar input, .toolbar select {
  min-width: 0;
  border: 1px solid var(--line);
  background: var(--panel);
  border-radius: 10px;
  padding: 0.45rem 0.7rem;
}
.toolbar input:focus, .toolbar select:focus, .name-box:focus, .formula-bar:focus {
  outline: 2px solid rgba(37, 99, 235, 0.22);
  border-color: #93c5fd;
}
.name-box { width: 104px; }
.formula-bar-wrap {
  position: relative;
  flex: 1 1 420px;
  min-width: 320px;
}
.formula-bar { width: 100%; }
.function-suggestions {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  z-index: 40;
  background: var(--panel);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  border-radius: 12px;
  min-width: 260px;
  max-width: 420px;
  overflow: hidden;
}
.function-suggestions button {
