  color: var(--muted);
  font-size: 0.84rem;
}
.legend-item { display: inline-flex; align-items: center; gap: 0.35rem; }
.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 2px solid currentColor;
  background: currentColor;
  opacity: 0.9;
}

.grid-scroll {
  position: relative;
  overflow: auto;
  min-height: 0;
  flex: 1 1 auto;
}

.grid {
  display: grid;
  grid-template-columns: var(--row-head-w) repeat(20, var(--cell-w));
  grid-auto-rows: var(--cell-h);
  width: calc(var(--row-head-w) + 20 * var(--cell-w));
  user-select: none;
}

.grid .corner,
.grid .col-head,
.grid .row-head,
.grid .cell {
  border-right: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  display: flex;
  align-items: center;
  padding: 0 0.45rem;
  position: relative;
}
.grid .corner,
.grid .col-head,
.grid .row-head {
  background: #f8fafc;
  font-size: 0.8rem;
  color: var(--muted);
  font-weight: 600;
}
.grid .corner { justify-content: center; }
.grid .col-head { justify-content: center; }
.grid .row-head { justify-content: flex-end; padding-right: 0.55rem; }
.grid .cell {
  background: white;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: 0.9rem;
}
.grid .cell:hover { background: #f8fafc; }
.grid .cell.selected {
  background: rgba(37, 99, 235, 0.09);
  box-shadow: inset 0 0 0 2px #2563eb;
  z-index: 2;
}
.grid .cell.selection-start::after {
  content: '';
  position: absolute;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  right: 2px;
  bottom: 2px;
  background: #2563eb;
}
.grid .cell.ref-highlight {
  background: rgba(245, 158, 11, 0.14);
  box-shadow: inset 0 0 0 2px #f59e0b;
}
.grid .cell.conflict {
  background: rgba(248, 113, 113, 0.12);
  box-shadow: inset 0 0 0 2px #ef4444;
}
.grid .cell.error { color: #dc2626; font-weight: 600; }
.grid .cell.numeric { text-align: right; justify-content: flex-end; }
.grid .cell.formula { font-variant-numeric: tabular-nums; }
.grid .cell.preview { background: #faf5ff; }
.grid .cell.local-only { background: #eff6ff; }
.grid .cell.remote-only { background: #ecfeff; }
.grid .cell.remote-selection {
  box-shadow: inset 0 0 0 2px var(--remote-color, #14b8a6);
}
.grid .cell.multi-remote {
  box-shadow: inset 0 0 0 2px var(--remote-color-a, #14b8a6), inset 0 0 0 4px var(--remote-color-b, #8b5cf6);
}
.grid .cell .value {
  width: 100%;
