}
.side-section:last-child { border-bottom: 0; overflow: auto; }
.side-section h2 {
  margin: 0 0 0.75rem;
  font-size: 0.93rem;
  color: #111827;
}
.side-section p,
.side-section li,
.side-section .muted {
  margin: 0;
  color: var(--muted);
  font-size: 0.88rem;
}
.presence-list,
.revision-list,
.history-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}
.presence-item,
.revision-item,
.history-item {
  border: 1px solid var(--line);
  background: #fff;
  border-radius: 10px;
  padding: 0.6rem 0.7rem;
}
.revision-item.active { border-color: #93c5fd; background: #eff6ff; }
.presence-item {
  display: flex;
  gap: 0.55rem;
  align-items: flex-start;
}
.presence-dot {
  flex: 0 0 auto;
  width: 12px;
  height: 12px;
  border-radius: 999px;
  margin-top: 0.2rem;
}
.presence-title { font-weight: 600; color: #111827; font-size: 0.88rem; }
.presence-meta,
.revision-meta,
.history-meta { color: var(--muted); font-size: 0.8rem; }
.revision-actions { display: flex; gap: 0.35rem; margin-top: 0.45rem; }
.revision-actions button { padding: 0.25rem 0.5rem; }
.history-row { display: flex; justify-content: space-between; gap: 0.5rem; }
.history-values { margin-top: 0.35rem; font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace; font-size: 0.78rem; white-space: pre-wrap; color: #374151; }

.conflict-banner {
  margin: 0.75rem 1rem 0;
  padding: 0.75rem 0.9rem;
  border-radius: 12px;
  background: #fef2f2;
  color: #991b1b;
  border: 1px solid #fecaca;
}
.preview-banner {
  margin: 0.75rem 1rem 0;
  padding: 0.75rem 0.9rem;
  border-radius: 12px;
  background: #f5f3ff;
  color: #5b21b6;
  border: 1px solid #ddd6fe;
}

.modal-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.55);
  display: grid;
  place-items: center;
  z-index: 100;
  padding: 1rem;
}
.modal {
  width: min(720px, 100%);
  background: white;
  border-radius: 18px;
  box-shadow: 0 30px 80px rgba(15, 23, 42, 0.3);
  border: 1px solid rgba(148, 163, 184, 0.25);
  overflow: hidden;
}
.modal header { padding: 1rem 1.1rem; border-bottom: 1px solid var(--line); }
.modal h1 { margin: 0 0 0.35rem; font-size: 1.2rem; }
.modal p { margin: 0; color: var(--muted); }
.modal .body { padding: 1rem 1.1rem 1.1rem; }
.user-card-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 0.75rem;
}
.user-card {
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 0.85rem;
  background: var(--panel-2);
}
.user-card .name { font-weight: 700; }
.user-card .id { color: var(--muted); font-size: 0.82rem; }
.user-card button { margin-top: 0.75rem; width: 100%; }

.inline-help { color: var(--muted); font-size: 0.8rem; }
.hidden { display: none !important; }

@media (max-width: 1120px) {
  .workspace { grid-template-columns: 1fr; }
  .side-panel { min-height: 320px; }
}
